10	)
11	
12	// TestExchangeCreateSaveFailureKeepsStateAndFreesRequestID 覆盖“身份有权操作、
13	// 患者未停用、绑定授权属于同一患者与接收方且当前有效、所选记录均为已生效并被
14	// 该授权自身覆盖、请求号尚未用过——全部业务条件都满足，但本地保存失败”的
15	// 交换创建场景。
16	//
17	// 失败必须以普通错误返回（不能伪装成 ErrConflict/ErrInvalidArgument/
18	// ErrAccessDenied），且正式交换列表、审计、临床记录当前版本与版本历史、
19	// 既有成功交换（标识、冻结包、摘要、回执）全部维持提交前状态；不允许出现
20	// 只有交换没有审计或只有审计没有交换的半成品。保存条件恢复后，失败的请求号
21	// 必须仍可使用；所选记录在失败后经过一次合法更正的，重试成功的包必须固化
22	// 重试时的当前版本与完整内容，而不是失败当时准备好的版本。关闭重开后同样
23	// 只见成功交换与其审计，失败尝试不留任何痕迹。
24	func TestExchangeCreateSaveFailureKeepsStateAndFreesRequestID(t *testing.T) {
25		dir := t.TempDir()
26		clk := &fakeClock{t: time.Date(2026, 5, 1, 9, 0, 0, 0, time.UTC)}
27		open := func() *Store {
28			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
29			if err != nil {
30				t.Fatalf("open: %v", err)
31			}
32			return s
33		}
34	
35		s := open()
36		p, err := s.RegisterPatient(doc, "交换保存失败患者")
37		if err != nil {
38			t.Fatal(err)
39		}
40		e, err := s.AddEncounter(doc, p.ID, time.Time{})
41		if err != nil {
42			t.Fatal(err)
43		}
44		// 两条已生效记录：诊断已更正到第 2 版，医嘱为第 1 版。
45		rd, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断v1内容")
46		if err != nil {
47			t.Fatal(err)
48		}
49		if _, err := s.ActivateRecord(doc, rd.ID); err != nil {
50			t.Fatal(err)
51		}
52		clk.t = clk.t.Add(time.Hour)
53		diagV2, err := s.CorrectRecord(doc, rd.ID, 1, "诊断v2内容", "录入笔误")
54		if err != nil {
55			t.Fatal(err)
56		}
57		ro, err := s.CreateDraft(doc, p.ID, e.ID, Order, "医嘱v1内容")
58		if err != nil {
59			t.Fatal(err)
60		}
61		if _, err := s.ActivateRecord(doc, ro.ID); err != nil {
62			t.Fatal(err)
63		}
64	
65		// 限定授权：不借整类范围，明确选出这两条已生效记录；授权本身属于该
66		// 患者与接收方，两条记录都由这同一条绑定授权自身覆盖。
67		authStart := clk.t.Add(-time.Minute)
68		authEnd := clk.t.Add(48 * time.Hour)
69		a, err := s.GrantSelective(doc, p.ID, rcv.ID, nil,
70			[]RecordSelection{
71				{EncounterID: e.ID, Category: Diagnosis, RecordID: rd.ID},
72				{EncounterID: e.ID, Category: Order, RecordID: ro.ID},
73			},
74			authStart, authEnd)
75		if err != nil {
76			t.Fatal(err)
77		}
78	
79		// 失败尝试之前，患者已有一份成功保存的交换，并且接收方已登记拒绝回执。
80		clk.t = clk.t.Add(time.Hour)
81		xPrior, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID}, "req-prior")
82		if err != nil {
83			t.Fatal(err)
84		}
85		clk.t = clk.t.Add(time.Hour)
86		if _, err := s.SubmitReceipt(rcv, xPrior.ID, xPrior.Digest, ReceiptRejected, "既有拒绝原因"); err != nil {
87			t.Fatal(err)
88		}
89		priorSnap, err := s.GetExchange(doc, p.ID, xPrior.ID)
90		if err != nil {
91			t.Fatal(err)
92		}
93	
94		// 提交前的正式基线：交换列表、审计、完整档案与接收方读取结果。
95		exchangesBefore, err := s.ListExchanges(doc, p.ID)
96		if err != nil {
97			t.Fatal(err)
98		}
99		auditBefore, err := s.AuditEvents(doc, p.ID)
100		if err != nil {
101			t.Fatal(err)
102		}
103		chartBefore, err := s.Chart(doc, p.ID)
104		if err != nil {
105			t.Fatal(err)
106		}
107		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
108		if err != nil {
109			t.Fatal(err)
110		}
111		createsBefore := auditActions(auditBefore)[ActionExchanged]
112	
113		// checkIntact 断言：失败尝试之后（以及重开之后），全部正式数据与提交前
114		// 逐项一致——没有新交换、没有新事件，临床记录与既有交换都未被改动。
115		checkIntact := func(label string, st *Store) {
116			t.Helper()
117	
118			xs, err := st.ListExchanges(doc, p.ID)
119			if err != nil {
120				t.Fatalf("%s: list exchanges: %v", label, err)
121			}
122			if !reflect.DeepEqual(xs, exchangesBefore) {
123				t.Fatalf("%s: exchange list changed:\nbefore: %+v\nafter:  %+v", label, exchangesBefore, xs)
124			}
125			for _, x := range xs {
126				if x.RequestID == "req-failed-save" {
127					t.Fatalf("%s: failed attempt surfaced as an exchange: %+v", label, x)
128				}
129			}
130	
131			// 既有交换的标识、冻结包版本与内容、摘要、状态与已有回执原样保留。
132			gotPrior, err := st.GetExchange(doc, p.ID, xPrior.ID)
133			if err != nil {
134				t.Fatalf("%s: get prior exchange: %v", label, err)
135			}
136			assertExchangeMatches(t, gotPrior, priorSnap, label+": prior exchange")
137	
138			audit, err := st.AuditEvents(doc, p.ID)
139			if err != nil {
140				t.Fatalf("%s: audit: %v", label, err)
141			}
142			if !reflect.DeepEqual(audit, auditBefore) {
143				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
144			}
145			if got := auditActions(audit)[ActionExchanged]; got != createsBefore {
146				t.Fatalf("%s: exchange_created events = %d, want %d", label, got, createsBefore)
147			}
148	
149			// 临床记录的当前版本、完整内容与版本历史不变。
150			chart, err := st.Chart(doc, p.ID)
151			if err != nil {
152				t.Fatalf("%s: chart: %v", label, err)
153			}
154			if !reflect.DeepEqual(chart.Records, chartBefore.Records) {
155				t.Fatalf("%s: clinical records changed:\nbefore: %+v\nafter:  %+v",
156					label, chartBefore.Records, chart.Records)
157			}
158	
159			// 接收方读取仍给出提交前的当前生效版本。
160			res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
161			if err != nil {
162				t.Fatalf("%s: receiver read: %v", label, err)
163			}
164			if !reflect.DeepEqual(res, readBefore) {
165				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
166			}
167		}
168	
169		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
170		// 与身份、授权、请求号或记录集合等业务校验无关。原数据文件先挪到旁边，
171		// 事后原样还原。
172		clk.t = clk.t.Add(time.Hour)
173		dataPath := filepath.Join(dir, dataName)
174		backupPath := dataPath + ".saved"
175		if err := os.Rename(dataPath, backupPath); err != nil {
176			t.Fatalf("backup data file: %v", err)
177		}
178		if err := os.Mkdir(dataPath, 0o755); err != nil {
179			t.Fatalf("block data path: %v", err)
180		}
181	
182		// 全部业务条件满足（含重复标识与乱序入参），仅本地保存失败：必须明确
183		// 报错，且不能伪装成请求号冲突、参数非法或访问拒绝等业务结果。
184		// （与更正保存失败的约定一致：非 nil 错误时返回值无意义，调用方必须
185		// 以错误为准；下面的正式状态断言保证它没有成为一份正式交换。）
186		if _, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
187			[]ID{ro.ID, rd.ID, ro.ID}, "req-failed-save"); err == nil {
188			t.Fatal("exchange creation must fail when local save fails")
189		} else if errors.Is(err, ErrConflict) || errors.Is(err, ErrInvalidArgument) ||
190			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) {
191			t.Fatalf("save failure surfaced as a business error: %v", err)
192		}
193		// 失败不能留下半截写入的临时文件。
194		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
195			t.Fatalf("failed save left a temp file: %v", statErr)
196		}
197	
198		// 失败后：交换列表、审计、临床记录与既有交换全部维持提交前状态。
199		checkIntact("after failed save", s)
200	
201		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
202		if err := s.Close(); err != nil {
203			t.Fatal(err)
204		}
205		if err := os.Remove(dataPath); err != nil {
206			t.Fatalf("unblock data path: %v", err)
207		}
208		if err := os.Rename(backupPath, dataPath); err != nil {
209			t.Fatalf("restore data file: %v", err)
210		}
211	
212		s2 := open()
213		t.Cleanup(func() { _ = s2.Close() })
214		// 重开后仍是操作前的正式数据：失败交换与其创建事件都不存在。
215		checkIntact("after reopen", s2)
216	
217		// 失败之后，所选诊断记录经历一次合法更正：当前推进到第 3 版。
218		clk.t = clk.t.Add(time.Hour)
219		diagV3, err := s2.CorrectRecord(doc, rd.ID, 2, "诊断v3内容", "失败后复核更正")
220		if err != nil {
221			t.Fatalf("legal correction after failed save: %v", err)
222		}
223		if diagV3.Number != 3 || diagV3.PrevID != diagV2.ID {
224			t.Fatalf("bad v3: %+v", diagV3)
225		}
226	
227		// 更正之后、重试之前的审计基线：相对失败前只多出这一条更正事件，
228		// 失败交换仍然没有任何事件。
229		auditAtRetry, err := s2.AuditEvents(doc, p.ID)
230		if err != nil {
231			t.Fatal(err)
232		}
233		if len(auditAtRetry) != len(auditBefore)+1 ||
234			!reflect.DeepEqual(auditAtRetry[:len(auditBefore)], auditBefore) {
235			t.Fatalf("audit after legal correction:\nbefore: %+v\nafter:  %+v", auditBefore, auditAtRetry)
236		}
237		if last := auditAtRetry[len(auditAtRetry)-1]; last.Action != ActionCorrected ||
238			last.ObjectID != rd.ID {
239			t.Fatalf("unexpected event from legal correction: %+v", last)
240		}
241		if xs, _ := s2.ListExchanges(doc, p.ID); len(xs) != 1 {
242			t.Fatalf("correction must not add exchanges: %d", len(xs))
243		}
244	
245		// 保存条件恢复后：同一内部使用者沿用失败的请求号、同一患者/接收方/
246		// 绑定授权与原记录集合再次创建。失败尝试不占用请求号，不得返回冲突。
247		clk.t = clk.t.Add(time.Hour)
248		xNew, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID,
249			[]ID{ro.ID, rd.ID, ro.ID}, "req-failed-save")
250		if err != nil {
251			t.Fatalf("retry with failed request id after recovery: %v", err)
252		}
253		if xNew.ID == "" || xNew.ID == xPrior.ID {
254			t.Fatalf("retry must create a new exchange, got %+v", xNew)
255		}
256		if xNew.Status != ExchangePending || xNew.Receipt != nil {
257			t.Fatalf("new exchange should be pending receipt without receipt: %+v", xNew)
258		}
259		if xNew.RequestID != "req-failed-save" || xNew.CreatorID != doc.ID {
260			t.Fatalf("new exchange header wrong: %+v", xNew)
261		}
262		if !xNew.CreatedAt.Equal(clk.t) {
263			t.Fatalf("created at %v != %v", xNew.CreatedAt, clk.t)
264		}
265	
266		// 新包固化的是“成功创建时”的当前版本与完整内容：诊断为 v3，
267		// 而不是失败当时准备好的 v2；医嘱仍为 v1。重复标识合并为两条。
268		if len(xNew.Package.Records) != 2 {
269			t.Fatalf("new package records = %d, want 2", len(xNew.Package.Records))
270		}
271		newByID := recordsByID(xNew.Package.Records)
272		gotDiag := newByID[rd.ID]
273		if gotDiag.VersionID != diagV3.ID || gotDiag.Version != 3 ||
274			gotDiag.Content != "诊断v3内容" || !gotDiag.EffectiveAt.Equal(diagV3.CreatedAt) {
275			t.Fatalf("new package froze stale v2 instead of current v3: %+v", gotDiag)
276		}
277		gotOrd := newByID[ro.ID]
278		if gotOrd.VersionID == "" || gotOrd.Version != 1 || gotOrd.Content != "医嘱v1内容" {
279			t.Fatalf("order record in new package wrong: %+v", gotOrd)
280		}
281		if xNew.Digest == "" || xNew.Digest == xPrior.Digest {
282			t.Fatalf("new package digest wrong: %q vs prior %q", xNew.Digest, xPrior.Digest)
283		}
284		if recomputed := packageDigest(xNew.Package); recomputed != xNew.Digest {
285			t.Fatalf("digest mismatch: got %q, recomputed %q", xNew.Digest, recomputed)
286		}
287	
288		// 成功这一步只新增一份待回执交换：列表恰为两份，原交换在前且原样保留，
289		// 没有为撤销失败而清空历史。
290		xs, err := s2.ListExchanges(doc, p.ID)
291		if err != nil {
292			t.Fatal(err)
293		}
294		if len(xs) != 2 || xs[0].ID != xPrior.ID || xs[1].ID != xNew.ID {
295			t.Fatalf("exchange list after retry: %+v", xs)
296		}
297		assertExchangeMatches(t, xs[0], priorSnap, "prior exchange after retry")
298		// 原交换包内的诊断仍是创建当时固化的 v2，未被后续更正或本次重试改写。
299		priorByID := recordsByID(xs[0].Package.Records)
300		if pr := priorByID[rd.ID]; pr.VersionID != diagV2.ID || pr.Version != 2 ||
301			pr.Content != "诊断v2内容" {
302			t.Fatalf("prior package mutated: %+v", pr)
303		}
304		if xs[0].Status != ExchangeRejected || xs[0].Receipt == nil ||
305			xs[0].Receipt.Outcome != ReceiptRejected || xs[0].Receipt.Reason != "既有拒绝原因" {
306			t.Fatalf("prior receipt lost: %+v", xs[0].Receipt)
307		}
308	
309		// 审计相对重试前基线只新增一条交换创建事件，记录本次成功操作的身份、
310		// 时间与交换标识；既有事件（含更正事件）原样保留。
311		audit, err := s2.AuditEvents(doc, p.ID)
312		if err != nil {
313			t.Fatal(err)
314		}
315		if len(audit) != len(auditAtRetry)+1 || !reflect.DeepEqual(audit[:len(auditAtRetry)], auditAtRetry) {
316			t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditAtRetry, audit)
317		}
318		last := audit[len(audit)-1]
319		if last.Action != ActionExchanged || last.ObjectType != "exchange" ||
320			last.ObjectID != xNew.ID || last.ActorID != doc.ID ||
321			last.PatientID != p.ID || !last.OccurredAt.Equal(clk.t) {
322			t.Fatalf("unexpected new audit event: %+v", last)
323		}
324		if got := auditActions(audit)[ActionExchanged]; got != createsBefore+1 {
325			t.Fatalf("exchange_created events = %d, want %d", got, createsBefore+1)
326		}
327	
328		// 关闭后从同一数据位置重新打开：成功交换与其审计完整可见，失败尝试
329		// 不能作为另一份交换或事件出现。
330		if err := s2.Close(); err != nil {
331			t.Fatal(err)
332		}
333		s3 := open()
334		t.Cleanup(func() { _ = s3.Close() })
335	
336		got, err := s3.GetExchange(doc, p.ID, xNew.ID)
337		if err != nil {
338			t.Fatalf("get new exchange after reopen: %v", err)
339		}
340		assertExchangeMatches(t, got, xNew, "new exchange after reopen")
341		gotList, err := s3.ListExchanges(doc, p.ID)
342		if err != nil {
343			t.Fatal(err)
344		}
345		if len(gotList) != 2 {
346			t.Fatalf("exchange count after reopen = %d, want 2", len(gotList))
347		}
348		assertExchangeMatches(t, gotList[0], priorSnap, "prior exchange after reopen")
349	
350		var createIDs []ID
351		for _, ev := range mustAudit(t, s3, p.ID) {
352			if ev.Action == ActionExchanged {
353				createIDs = append(createIDs, ev.ObjectID)
354			}
355		}
356		if !reflect.DeepEqual(createIDs, []ID{xPrior.ID, xNew.ID}) {
357			t.Fatalf("exchange_created events after reopen = %v, want [%q %q]",
358				createIDs, xPrior.ID, xNew.ID)
359		}
360	
361		// 既有公开行为保留：同请求号同参数重试返回本次成功交换，不另建交换或事件。
362		retry, err := s3.CreateExchange(doc, p.ID, rcv.ID, a.ID,
363			[]ID{rd.ID, ro.ID}, "req-failed-save")
364		if err != nil {
365			t.Fatalf("idempotent retry after reopen: %v", err)
366		}
367		if retry.ID != xNew.ID {
368			t.Fatalf("retry returned %q, want %q", retry.ID, xNew.ID)
369		}
370		if xs, _ := s3.ListExchanges(doc, p.ID); len(xs) != 2 {
371			t.Fatalf("idempotent retry changed exchange count: %d", len(xs))
372		}
373		if evs := mustAudit(t, s3, p.ID); len(evs) != len(auditAtRetry)+1 {
374			t.Fatalf("idempotent retry added audit events: %d", len(evs))
375		}
376	}
377

