176	// ---- 首次创建返回的交换：本地篡改不入库 ----
177	
178	func TestCreateExchangeResultIsDetachedFromStore(t *testing.T) {
179		f := setupExchange(t)
180		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
181			[]ID{f.diag, f.ord}, "req-iso-create")
182		if err != nil {
183			t.Fatal(err)
184		}
185		want := snapshotExchange(x)
186	
187		auditBefore := len(mustAudit(t, f.s, f.pid))
188	
189		tamperExchangeResult(&x)
190	
191		// 重新查看原交换：完整包、原摘要、原状态、无回执。
192		got, err := f.s.GetExchange(doc, f.pid, want.ID)
193		if err != nil {
194			t.Fatalf("re-get after local tamper: %v", err)
195		}
196		assertExchangeMatches(t, got, want, "GetExchange after tampering create result")
197	
198		// 列表视图同样保持原样。
199		lst, err := f.s.ListExchanges(doc, f.pid)
200		if err != nil {
201			t.Fatal(err)
202		}
203		if len(lst) != 1 {
204			t.Fatalf("list len = %d, want 1", len(lst))
205		}
206		assertExchangeMatches(t, lst[0], want, "ListExchanges after tampering create result")
207	
208		// 纯本地修改不产生审计事件。
209		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
210			t.Fatalf("local tamper changed audit count: before=%d after=%d", auditBefore, got)
211		}
212	}
