214	// ---- 相同请求重试：被篡改的首次结果不影响重试，重试结果也独立 ----
215	
216	func TestIdempotentRetryResultIsDetached(t *testing.T) {
217		f := setupExchange(t)
218		first, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
219			[]ID{f.ord, f.diag}, "req-iso-retry")
220		if err != nil {
221			t.Fatal(err)
222		}
223		want := snapshotExchange(first)
224	
225		// 改掉首次返回的交换。
226		tamperExchangeResult(&first)
227	
228		// 相同请求重试：必须返回库内原交换，而不是被首次结果污染的内容。
229		second, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
230			[]ID{f.diag, f.ord, f.diag}, "req-iso-retry")
231		if err != nil {
232			t.Fatalf("idempotent retry after local tamper: %v", err)
233		}
234		assertExchangeMatches(t, second, want, "retry result after first result tampered")
235	
236		// 再改掉重试返回的交换，库内仍保持原样。
237		tamperExchangeResult(&second)
238		got, err := f.s.GetExchange(doc, f.pid, want.ID)
239		if err != nil {
240			t.Fatalf("re-get after tampering retry result: %v", err)
241		}
242		assertExchangeMatches(t, got, want, "GetExchange after tampering retry result")
243	
244		if n := auditActions(mustAudit(t, f.s, f.pid))[ActionExchanged]; n != 1 {
245			t.Fatalf("exchange_created audit events = %d, want 1", n)
246		}
247	}
