249	// ---- 按患者查看：先后取得的两份结果彼此独立、也独立于库内交换 ----
250	
251	func TestGetExchangeCopiesAreIndependent(t *testing.T) {
252		f := setupExchange(t)
253		created, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
254			[]ID{f.diag, f.ord}, "req-iso-get")
255		if err != nil {
256			t.Fatal(err)
257		}
258	
259		g1, err := f.s.GetExchange(doc, f.pid, created.ID)
260		if err != nil {
261			t.Fatal(err)
262		}
263		want := snapshotExchange(g1)
264	
265		// 先取得两份独立结果。
266		g2, err := f.s.GetExchange(doc, f.pid, created.ID)
267		if err != nil {
268			t.Fatal(err)
269		}
270	
271		// 修改第一份：第二份仍保留取得时的内容。
272		tamperExchangeResult(&g1)
273		assertExchangeMatches(t, g2, want, "previously fetched copy after another copy tampered")
274	
275		// 库内交换不变。
276		g3, err := f.s.GetExchange(doc, f.pid, created.ID)
