	g2, err := f.s.GetExchange(doc, f.pid, created.ID)
	if err != nil {
		t.Fatal(err)
	}

	// 修改第一份：第二份仍保留取得时的内容。
	tamperExchangeResult(&g1)
	assertExchangeMatches(t, g2, want, "previously fetched copy after another copy tampered")

	// 库内交换不变。
