	tamperExchangeResult(&g2)
	g4, err := f.s.GetExchange(doc, f.pid, created.ID)
	if err != nil {
		t.Fatal(err)
	}
	assertExchangeMatches(t, g4, want, "fresh GetExchange after tampering second copy")
}

